## Operador pipe (|> ou %>%)

:::: {.columns}

::: {.column width="50%"}
### Definindo função Fibonacci


::: {.cell}

```{.r .cell-code}
fibonacci <- function(dataframe, x) {
  vetor <- dataframe[, x]
  soma <- rep(0, length(vetor))
  for (j in 1:length(vetor)) {
    a <- 0
    b <- 1
    num <- a+b
    soma[j] <- 0
    for (i in 1:vetor[j]) {
      num <- a+b
      a <- b
      b <- num
      soma[j] <- soma[j]+a
    }
  }
  return(soma)
}
```
:::

:::

::: {.column width="50%"}
### Aplicando operador pipe


::: {.cell}

```{.r .cell-code}
# dataframe
dados <- data.frame(a = seq(1, 5))
str(dados)
```

::: {.cell-output .cell-output-stdout}

```
'data.frame':	5 obs. of  1 variable:
 $ a: int  1 2 3 4 5
```


:::

```{.r .cell-code}
# aplicando a função fibonacci
fibonacci(dados, "a")
```

::: {.cell-output .cell-output-stdout}

```
[1]  1  2  4  7 12
```


:::

```{.r .cell-code}
# aplicando a função com o operador pipe
dados |> 
  fibonacci("a")
```

::: {.cell-output .cell-output-stdout}

```
[1]  1  2  4  7 12
```


